import sys

def solve():
    data = sys.stdin.read().splitlines()
    if not data:
        return

    n = int(data[0].strip())
    ops = data[1:n+1]

    typedefs = {}

    def parse_type(s):
        amp_count = 0
        star_count = 0
        i = 0
        while i < len(s) and s[i] == '&':
            amp_count += 1
            i += 1
        while i < len(s) and s[i] == '*':
            star_count += 1
            i += 1
        base = s[i:]
        return base, amp_count, star_count

    def resolve_type(base_name, amp_count, star_count):
        if base_name in ('void', 'errtype'):
            current_base = base_name
            current_amps = amp_count
            current_stars = star_count
        else:
            if base_name not in typedefs:
                return 'errtype', 0
            resolved_base, resolved_amps, resolved_stars = typedefs[base_name]
            current_base = resolved_base
            current_amps = resolved_amps + amp_count
            current_stars = resolved_stars + star_count

        if current_base == 'errtype':
            return 'errtype', 0

        net = current_stars - current_amps
        if net < 0:
            return 'errtype', 0
        return 'void', net

    output_lines = []

    for line in ops:
        parts = line.split()
        if parts[0] == 'typedef':
            A_str = parts[1]
            B_name = parts[2]
            base, amps, stars = parse_type(A_str)
            res_base, res_stars = resolve_type(base, amps, stars)
            typedefs[B_name] = (res_base, res_stars)
        elif parts[0] == 'typeof':
            A_str = parts[1]
            base, amps, stars = parse_type(A_str)

            if base in ('void', 'errtype'):
                current_base = base
                current_amps = amps
                current_stars = stars
            else:
                if base not in typedefs:
                    res_base = 'errtype'
                    res_stars = 0
                else:
                    resolved_base, resolved_amps, resolved_stars = typedefs[base]
                    current_base = resolved_base
                    current_amps = resolved_amps + amps
                    current_stars = resolved_stars + stars

                if current_base == 'errtype':
                    res_base = 'errtype'
                    res_stars = -1
                else:
                    res_base = current_base
                    res_stars = current_stars

            if res_base == 'errtype' or (res_base == 'void' and res_stars < 0):
                output_lines.append('errtype')
            else:
                output_lines.append('void' + '*' * res_stars)

    for line in output_lines:
        print(line)

if __name__ == "__main__":
    solve()
